class TestWhileLoop:
    def test_while_counts_to_three(self):
        # Uses mutable state; assumes your interpreter supports assignment
        assert run("""
            let x = 0 in
            while x < 3 do
                x = x + 1
            done;
            x
        """) == 3

    def test_while_body_never_runs(self):
        assert run("""
            let x = 0 in
            while false do
                x = x + 1
            done;
            x
        """) == 0

    def test_while_returns_zero(self):
        assert run("while false do 1 done") == 0
